#include "DSP/PitchProcessor.h"
#include "Core/SongTime.h"
#include <cmath>
namespace myvocal { double PitchProcessor::semitoneAt(const Note&n,double t){double v=n.getPitchCurve().evaluateSmooth(std::clamp(t,0.0,1.0));const auto&vb=n.getVibrato();if(vb.enabled&&vb.length>0&&t>=vb.delay&&t<=vb.delay+vb.length){double u=(t-vb.delay)/vb.length;double env=std::sin(std::clamp(u,0.0,1.0)*3.141592653589793);v+=vb.depth*0.5*env*std::sin(2*3.141592653589793*vb.rate*(t-vb.delay));}return v;} void PitchProcessor::applyVibrato(const Note&n,std::vector<float>&samples,double sr){if(!n.getVibrato().enabled||n.getVibrato().depth==0||samples.empty())return;const auto&v=n.getVibrato();for(size_t i=0;i<samples.size();++i){double t=(double)i/sr;double delay=v.delay;double len=v.length;if(t<delay||t>delay+len)continue;double u=(t-delay)/std::max(1e-9,len);double env=std::sin(std::clamp(u,0.0,1.0)*3.141592653589793);double gain=std::pow(2.0,(v.depth*env*std::sin(2*3.141592653589793*v.rate*(t-delay)))/12.0);samples[i]=static_cast<float>(samples[i]*std::min(1.5,gain));}} }
